# -*- coding: utf-8 -*-
"""
Ghi cac vector NGUYEN VAN trich tu app Ghi chu Xiaomi 2.4.2.5 (xem docs/SPEC-GOC.md)
vao res/drawable cua app.

Vi sao la script chu khong chep tay: 12 tep, moi tep mot pathData dai vai nghin
ky tu — chep tay la som muon rung mot so. Chay lai script la co lai dung bo goc.

Mau trong tep chi la mac dinh; cho nao can doi theo sang/toi thi code to lai
bang setColorFilter.

Chay:  python tools/ghi_icon_goc.py
"""
import io
import os

RA = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'app', 'src', 'main', 'res', 'drawable')

DAU = '<?xml version="1.0" encoding="utf-8"?>\n'


def ghi(ten, chu_thich, w, h, vw, vh, paths):
    s = DAU + '<!-- ' + chu_thich + ' -->\n'
    s += '<vector xmlns:android="http://schemas.android.com/apk/res/android"\n'
    s += '    android:width="%sdp" android:height="%sdp"\n' % (w, h)
    s += '    android:viewportWidth="%s" android:viewportHeight="%s">\n' % (vw, vh)
    for mau, d, extra in paths:
        s += '    <path android:fillColor="' + mau + '"' + extra + '\n        android:pathData="' + d + '"/>\n'
    s += '</vector>\n'
    io.open(os.path.join(RA, ten), 'w', encoding='utf-8').write(s)
    print('ghi', ten)


